import { cp, mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(scriptDir, "..");
const bridgeRoot = path.join(repoRoot, "discord_nas_bridge");
const bundleRoot = path.join(bridgeRoot, "app");
const relativeBundleRoot = path.relative(bridgeRoot, bundleRoot);

if (relativeBundleRoot.startsWith("..") || path.isAbsolute(relativeBundleRoot)) {
  throw new Error(`Refusing to prepare bundle outside discord_nas_bridge: ${bundleRoot}`);
}

await rm(bundleRoot, { recursive: true, force: true });
await mkdir(bundleRoot, { recursive: true });

await cp(path.join(repoRoot, "package.json"), path.join(bundleRoot, "package.json"));
await cp(path.join(repoRoot, "package-lock.json"), path.join(bundleRoot, "package-lock.json"));
await cp(path.join(repoRoot, "tsconfig.json"), path.join(bundleRoot, "tsconfig.json"));
await cp(path.join(repoRoot, "src"), path.join(bundleRoot, "src"), { recursive: true });

const generatedAt = new Date().toISOString();
await writeFile(
  path.join(bundleRoot, ".bundle-generated.txt"),
  [
    "Generated by scripts/prepare-nas-bundle.mjs",
    `Generated at: ${generatedAt}`,
    "",
    "This app/ directory is a deploy bundle for Synology/NAS Docker builds.",
    "Do not edit it manually. Regenerate it from the repository root before upload.",
    "",
  ].join("\n"),
  "utf8",
);

console.log(`NAS bundle prepared: ${bundleRoot}`);
